import numpy as np
import pandas as pd

from pandas import Timedelta, TimedeltaIndex

results = {}

def record(name, fn):
    try:
        out = fn()
        # Convert TimedeltaIndex/ndarray-like to repr-stable strings
        if isinstance(out, (TimedeltaIndex, pd.Index)):
            results[name] = {
                "type": type(out).__name__,
                "repr": repr(out),
            }
        else:
            results[name] = {"type": type(out).__name__, "repr": repr(out)}
    except Exception as e:
        results[name] = {
            "type": type(e).__name__,
            "message": str(e),
        }

# 1) int overflow via large days converted to ns
record("mul_int_overflow_100000D_x2", lambda: (
    (TimedeltaIndex([Timedelta(100000,'D').as_unit('ns')]*2) * 2),
))

# 2) uint overflow above int64.max
u = np.uint64(2**63 + 5)
record("mul_uint_overflow_u64", lambda: (
    (TimedeltaIndex([Timedelta(1,'ns')]*2) * u),
))

# 3) int64.min boundary misread as iNaT
record("mul_hits_int64_min_returns_nat", lambda: (
    TimedeltaIndex([Timedelta(-(2**62),'ns'), Timedelta(-(2**62),'ns')]) * 2
))

# 4) float overflow saturates
record("mul_float_overflow_2p5", lambda: (
    TimedeltaIndex([Timedelta(100000,'D').as_unit('ns')]*2) * np.float64(2.5)
))

# 5) float boundary 2**63 slips past check
record("mul_float_overflow_boundary_2p0", lambda: (
    TimedeltaIndex([Timedelta(2**62,'ns')]*2) * 2.0
))

# 6) inf handling
record("mul_inf", lambda: (
    TimedeltaIndex([Timedelta(1,'ns')]*2) * np.inf
))
record("mul_neg_inf", lambda: (
    TimedeltaIndex([Timedelta(1,'ns')]*2) * -np.inf
))

# 7) nan multiplier preserves NaT
record("mul_nan_returns_nat", lambda: (
    TimedeltaIndex([Timedelta(1,'ns'), Timedelta(2,'ns')]) * np.nan
))

# 8) NaT preservation
record("mul_preserve_nat", lambda: (
    TimedeltaIndex([Timedelta(5,'ns'), pd.NaT]) * 2
))
record("mul_preserve_nat_float", lambda: (
    TimedeltaIndex([Timedelta(5,'ns'), pd.NaT]) * 2.0
))

# 9) division overflow
record("div_0p4_overflow", lambda: (
    TimedeltaIndex([Timedelta(2**62,'ns')]*2) / 0.4
))
record("floordiv_0p4_overflow", lambda: (
    TimedeltaIndex([Timedelta(2**62,'ns')]*2) // 0.4
))

# 10) zero and nan divisors yield NaT unchanged
record("div_0p0", lambda: (
    TimedeltaIndex([Timedelta(2**62,'ns'), pd.NaT]) / 0.0
))
record("floordiv_0p0", lambda: (
    TimedeltaIndex([Timedelta(2**62,'ns'), pd.NaT]) // 0.0
))
record("div_nan", lambda: (
    TimedeltaIndex([Timedelta(2**62,'ns'), pd.NaT]) / np.nan
))

# Emit as a single structured value for this probe
probe_value = results

# tool expects probe(...) calls, but we just leave a final variable with content
probe(probe_value)

